<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class Event extends Model { public function organisationUnit(){ return $this->belongsTo(OrganisationUnit::class); } protected $fillable=['organisation_unit_id','title','category','description','starts_at','ends_at','venue','theme','speaker','organizer','target_age_categories','registration_required','fee','currency','capacity','registration_deadline','poster_path','status','created_by']; protected $casts=['starts_at'=>'datetime','ends_at'=>'datetime','registration_deadline'=>'datetime','target_age_categories'=>'array','registration_required'=>'boolean','fee'=>'decimal:2']; public function registrations(){return $this->hasMany(EventRegistration::class);} }
